import React from 'react';
import { useNavigate } from 'react-router-dom';

const services = [
  { id: 1, title: "Tiệc cưới", desc: "Không gian cưới sang trọng và lãng mạn.", path: "/service/wedding" },
  { id: 2, title: "Sinh nhật", desc: "Tổ chức sinh nhật sáng tạo cho mọi lứa tuổi.", path: "/service/birthday" },
  { id: 3, title: "Sự kiện công ty", desc: "Sự kiện doanh nghiệp chuyên nghiệp và chỉn chu.", path: "/service/corporate" },
  { id: 4, title: "Trang trí chủ đề", desc: "Biến tấu không gian với decor theo concept.", path: "/service/decor" },
];

function Home() {
  const navigate = useNavigate();
  const isLoggedIn = !!JSON.parse(localStorage.getItem("currentUser"));

  const handleClick = (path) => {
    if (isLoggedIn) navigate(path);
    else {
      alert("Vui lòng đăng nhập để xem chi tiết dịch vụ.");
      navigate("/login");
    }
  };

  return (
    <div className="container py-5">
      <div className="text-center mb-5">
        <h1 className="fw-bold text-primary">PartyPlanner Pro</h1>
        <p className="fs-5 text-muted">
          Nơi biến mọi khoảnh khắc thành lễ hội đáng nhớ. Từ cưới hỏi đến sinh nhật, từ sự kiện công ty đến trang trí chủ đề!
        </p>
      </div>
      <div className="row g-4">
        {services.map(service => (
          <div className="col-md-6 col-lg-3" key={service.id}>
            <div className="card h-100 border-0 shadow text-center p-3 hover-shadow">
              <h5 className="card-title mt-3">{service.title}</h5>
              <p className="card-text">{service.desc}</p>
              <button className="btn btn-outline-primary mt-auto" onClick={() => handleClick(service.path)}>
                Khám phá
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Home;
